import{_ as t,c as o,b as n,o as r}from"./app-BQtIcdRy.js";const a={};function s(i,e){return r(),o("div",null,e[0]||(e[0]=[n('<p>With <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace</a> App, You can convert your store into a marketplace where multiple sellers can register and sell their products all over the globe.</p><p>You might know about <a href="https://www.etsy.com/" target="_blank" rel="noopener noreferrer">Etsy</a>, a well-known online global marketplace that focuses on selling handmade goods and vintage items.</p><p>So, if Your sellers have their stores on Etsy too and they want to sell their Etsy store&#39;s products on the admin&#39;s marketplace then use the <strong>Seller</strong> <strong>Etsy Connector</strong> App.</p><p>To connect the Etsy store with the admin&#39;s marketplace, Seller needs to &quot;<strong>Create An App</strong>&quot; on his/her Etsy Store and get the API &amp; Secret Key to establish the connection.</p><p>Admin can enable this feature app by approving the additional charge of $25 USD/month.</p><p>Thus, allows sellers to import their Etsy store&#39;s products to the admin&#39;s Multivendor Marketplace. Accordingly, manage the inventory at both ends.</p><p>Let&#39;s Explore the Features in detail.</p><h3 id="additional-features" tabindex="-1"><a class="header-anchor" href="#additional-features"><span>Additional Features</span></a></h3><ul><li>Admin can allow the marketplace sellers to connect their Etsy stores with the admin&#39;s Shopify store.</li><li>Further, the seller will create an app on his/her Etsy store and get the API &amp; Secret key as Etsy store details.</li><li>Products created on Etsy can be imported using the product&#39;s listing ID(s) with &quot;approval pending state&quot;.</li><li>The seller can import products in bulk using CSV files having multiple product listing IDs.</li><li>Moreover, the admin can approve or deny the products imported by the Etsy sellers.</li><li>If an order is placed on the admin&#39;s store, the same will be updated on Etsy too.</li><li>If an order is placed on Etsy, the seller will have the option to import orders either by &quot;Order status&quot; or by &quot;Receipt IDs&quot;.</li><li>Orders can be imported in bulk using the CSV file of the order&#39;s receipt IDs.</li><li><strong><a href="https://webkul.com/blog/shopify-multivendor-marketplace-slot-pricing/" target="_blank" rel="noopener noreferrer">Slot Pricing</a> is compatible</strong> with this connector.</li><li>Both admin &amp; seller can now sync the seller’s products in any state from the “Product Listing” section of their respective panels.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Product-Admin-2-1200x597.png" alt="sync with seller store"></p><h3 id="limitations-of-the-etsy-connector-app" tabindex="-1"><a class="header-anchor" href="#limitations-of-the-etsy-connector-app"><span>Limitations of the Etsy Connector app</span></a></h3><ul><li>Only Physical products will be imported from Etsy to Shopify.</li><li>Variations should be less than OR equal to 100.</li><li>The option name should be less than OR equal to 3.</li><li>Imported Products will not be updated automatically at the Shopify end.</li><li>100 Orders will be imported by selecting &quot;Order Status&quot; and the rest of the orders will be imported by &quot;receipt IDs&quot;.</li></ul><h3 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>Seller End</span></a></h3><p>To get this feature app, the admin needs to visit the &quot;<strong>Feature Apps</strong>&quot; section of the Multivendor app and go through below mentioned steps:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/12/Dashboard-Admin-2.png" alt="S1"></p><p>In Feature Apps section, Search for &quot;<strong>Shopify-Etsy Connector</strong> app&quot;.</p><p>Further, click on the &quot;<strong>Install</strong>&quot; button to get this feature app.</p><p>Tap the &quot;<strong>Agree</strong>&quot; button and Proceed to approve the charge.</p><p>Further, click on the &quot;<strong>Approve Charge</strong>&quot; button.</p><p>Once done, You will get the Etsy Connector feature app installed on your Marketplace.</p><h2 id="product-detail-configuration-admin-end" tabindex="-1"><a class="header-anchor" href="#product-detail-configuration-admin-end"><span>PRODUCT DETAIL CONFIGURATION: Admin End</span></a></h2><p>Now, the admin needs to select the Etsy connector from the “<strong>Connector Configuration</strong>” menu of the app.</p><p>Go to Configuration&gt;&gt;Product Detail Configuration&gt;&gt;Select the Connector.</p><p>Now, he can enable/disable other tabs for this section:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/03/11122526/AwesomeScreenshot-Connector-Configurations-Admin-2019-07-11-17-07-82.png" alt="AwesomeScreenshot-Connector-Configurations-Admin-2019-07-11-17-07-82"></p><h3 id="charge-tax-on-products" tabindex="-1"><a class="header-anchor" href="#charge-tax-on-products"><span>Charge Tax On Products</span></a></h3><p>From the Connector Configuration, you can choose how you want to charge taxes on products synced with the seller&#39;s Etsy store.</p><p>You can choose to charge tax on products. You can select whether the tax rates will be applied from your Shopify store or from the seller&#39;s Etsy store.</p><p>Also, You can choose &quot;not to charge taxes&quot; on the products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/Connector-Configurations-Admin-1200x597.png" alt="Connector-Configurations-Admin"></p><p>That&#39;s all about the Configuration done from the admin end. Furthermore, moving on to the Seller end</p><p>And let&#39;s see how the Sellers manage the configuration to connect their Etsy store with the admin&#39;s marketplace.</p><h3 id="etsy-configuration" tabindex="-1"><a class="header-anchor" href="#etsy-configuration"><span>Etsy Configuration</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/12/Dashboard-Seller-•-Multivendor-MarketPlace-2.png" alt="S2"></p><p>As soon as the admin installs the Shopify-Etsy Connector feature app in the Multivendor Marketplace App. Furthermore, the Configuration menu in the Seller Panel gains a new sub-menu.</p><h3 id="etsy-app-configuration" tabindex="-1"><a class="header-anchor" href="#etsy-app-configuration"><span>Etsy App Configuration</span></a></h3><p>To set up the <strong>&quot;Etsy App Configuration&quot;</strong>, sellers can authenticate the Etsy connector app by clicking the <strong>&quot;Authenticate Your App&quot;</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1691764630573-1200x616.png" alt="screenshot_1691764630573"></p><p>This will open a new page where you should select <strong>&quot;Authenticate Multivendor-Etsy Connector App&quot;</strong>.</p><p>From there, log in to your Handmade Marketplace account, complete the app authentication, and you will be automatically directed to the Multivendor Seller panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/01/etsy-1200x612.webp" alt="Handmade Marketplace"></p><h3 id="inventory-sync-timing" tabindex="-1"><a class="header-anchor" href="#inventory-sync-timing"><span>Inventory Sync Timing</span></a></h3><p>In the &quot;Inventory Sync Timing&quot; section of the Etsy Configuration, sellers have the ability to specify the three-time slots for synchronizing their product inventory.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1691765022525-1200x610.png" alt="screenshot_1691765022525"></p><h3 id="bulk-update-product-inventory-from-etsy" tabindex="-1"><a class="header-anchor" href="#bulk-update-product-inventory-from-etsy"><span>Bulk update product inventory from Etsy</span></a></h3><p>The sellers also have the option to manually synchronize their product inventory from Etsy in bulk.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1697212932233.png" alt="screenshot_1697212932233"></p><h3 id="tag-mapping" tabindex="-1"><a class="header-anchor" href="#tag-mapping"><span>Tag Mapping</span></a></h3><p>Clicking on &quot;Tag Mapping,&quot; sellers will have the option to map product tags. Sellers can also disable or delete mapped tags according to their needs.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1691765238797-1200x614.png" alt="screenshot_1691765238797"></p><h3 id="import-products" tabindex="-1"><a class="header-anchor" href="#import-products"><span>Import Products</span></a></h3><p>Once the Seller authenticates the Etsy Connector app, the system adds an &quot;Import Products&quot; button to the same page.</p><p>Further, by clicking on the &quot;Import Product&quot; button, the Seller will get two methods to import his Etsy store&#39;s product to Shopify.</p><h3 id="method-1-using-single-or-comma-separated-listing-id-s" tabindex="-1"><a class="header-anchor" href="#method-1-using-single-or-comma-separated-listing-id-s"><span><strong>Method 1: Using single or comma-separated Listing ID(s)</strong></span></a></h3><p>By using this method, the Seller should enter the Listing ID(s) of the products they wish to import and then click the &quot;Import&quot; button.</p><p>This action will import the specified products from Etsy to the Multivendor Marketplace app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/08/screenshot_1691753740352-1200x616.webp" alt="screenshot_1691753740352"></p><h3 id="method-2-by-csv" tabindex="-1"><a class="header-anchor" href="#method-2-by-csv"><span>Method 2: By CSV</span></a></h3><p>By using this method the sellers can add their products in bulk via CSV</p><p>They can download the example product listing CSV to add their products</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1697213257254.png" alt="screenshot_1697213257254"></p><h3 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>Admin End</span></a></h3><p>Once the products get imported into the Multivendor app, they will be in an approval pending state at both ends (admin and seller end).</p><p>It is up to the admin if he/she approves or rejects the products to be sold on the admin&#39;s marketplace.</p><p>If the admin denies the imported product, he/she needs to add a reason for the rejection.</p><p><strong>Let&#39;s See how it Works:</strong></p><p>Suppose a product is added on Etsy and Seller has imported this product from Etsy to Multivendor App.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/12/Screenshot-27.png" alt="s33"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/12/Screenshot-28.png" alt="s22"></p><p>This is how the imported product appears on the Multivendor App.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/12/Product-Admin-1.png" alt="s11"></p><p>Admin can enable, deny or delete any imported products from his end.</p><p>Once the admin approves any product, the same will reflect in the Seller panel of the Multivendor App.</p><h3 id="price-rule" tabindex="-1"><a class="header-anchor" href="#price-rule"><span>Price Rule</span></a></h3><p>Let the sellers create price rules to manage the product price of their PrestaShop store to the merchant’s store.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/01/Dashboard-Seller-•-Multivendor-MarketPlace-1.png" alt="Price rule "></p><p>Sellers will have a new menu named <strong>Connector Price Rule</strong> in the configuration menu of the app.</p><p>From here, the seller can create price rules based on which the seller’s product price will be calculated on the merchant’s store.</p><p>Clicking the <strong>Connector Price Rule</strong>, the seller needs to enable “Price Rule” status and select the options as increase/decrease price.</p><p>The price will be changed by a fixed amount or a percentage amount, enter the amount that needs to be changed.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/01/Price-Rule-•-Multivendor-MarketPlace.png" alt="price rule"></p><p>Further, enable the checkbox to update the already synced product’s price at the merchant’s store as per the price rule created.</p><p>This way, sellers can create price rules from their respective seller panels based on which product price of the seller’s store will be calculated at the merchant’s store.</p><p>That&#39;s all about the Shopify-Etsy Connector Feature App using which the admin can allow his/her sellers to connect their Etsy Store with the admin&#39;s Shopify store with ease.</p><h2 id="demo-details" tabindex="-1"><a class="header-anchor" href="#demo-details"><span>Demo Details</span></a></h2><p>Moreover, follow the below links and credentials to use the demo of the Multivendor Marketplace app:</p><p><a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/pages/seller-profile</a></p>',87)]))}const p=t(a,[["render",s]]),c=JSON.parse('{"path":"/classic/Featured-App/Connector/SHOPIFY%20ETSY%20CONNECTOR.html","title":"SHOPIFY ETSY CONNECTOR","lang":"en-US","frontmatter":{"title":"SHOPIFY ETSY CONNECTOR","description":"SHOPIFY ETSY CONNECTOR","date":"2025-07-20T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Additional Features","slug":"additional-features","link":"#additional-features","children":[]},{"level":3,"title":"Limitations of the Etsy Connector app","slug":"limitations-of-the-etsy-connector-app","link":"#limitations-of-the-etsy-connector-app","children":[]},{"level":3,"title":"Seller End","slug":"seller-end","link":"#seller-end","children":[]},{"level":2,"title":"PRODUCT DETAIL CONFIGURATION: Admin End","slug":"product-detail-configuration-admin-end","link":"#product-detail-configuration-admin-end","children":[{"level":3,"title":"Charge Tax On Products","slug":"charge-tax-on-products","link":"#charge-tax-on-products","children":[]},{"level":3,"title":"Etsy Configuration","slug":"etsy-configuration","link":"#etsy-configuration","children":[]},{"level":3,"title":"Etsy App Configuration","slug":"etsy-app-configuration","link":"#etsy-app-configuration","children":[]},{"level":3,"title":"Inventory Sync Timing","slug":"inventory-sync-timing","link":"#inventory-sync-timing","children":[]},{"level":3,"title":"Bulk update product inventory from Etsy","slug":"bulk-update-product-inventory-from-etsy","link":"#bulk-update-product-inventory-from-etsy","children":[]},{"level":3,"title":"Tag Mapping","slug":"tag-mapping","link":"#tag-mapping","children":[]},{"level":3,"title":"Import Products","slug":"import-products","link":"#import-products","children":[]},{"level":3,"title":"Method 1: Using single or comma-separated Listing ID(s)","slug":"method-1-using-single-or-comma-separated-listing-id-s","link":"#method-1-using-single-or-comma-separated-listing-id-s","children":[]},{"level":3,"title":"Method 2: By CSV","slug":"method-2-by-csv","link":"#method-2-by-csv","children":[]},{"level":3,"title":"Admin End","slug":"admin-end","link":"#admin-end","children":[]},{"level":3,"title":"Price Rule","slug":"price-rule","link":"#price-rule","children":[]}]},{"level":2,"title":"Demo Details","slug":"demo-details","link":"#demo-details","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/Featured-App/Connector/SHOPIFY ETSY CONNECTOR.md"}');export{p as comp,c as data};
